import React, { useState } from "react";
import { useLanguage } from "./Languagecontext";
import { Routes, Route, useNavigate } from "react-router-dom";
import Login from "./views/Login";
import FarmerDashboard from "./views/FarmerDashboard";
import WorkerDashboard from "./views/WorkerDashboard";
import "./App.css";


// Welcome Screen
function WelcomeScreen() {
  const { language, changeLanguage, t } = useLanguage();
  const navigate = useNavigate();

  const [selectedLanguage, setSelectedLanguage] = useState(
    language || ""
  );

  const [started, setStarted] = useState(Boolean(language));

  const handleContinue = () => {
    if (!selectedLanguage) {
      alert("Please select a language / దయచేసి భాషను ఎంచుకోండి");
      return;
    }

    changeLanguage(selectedLanguage);
    setStarted(true);
  };

  const handleLanguageChange = (newLanguage) => {
    setSelectedLanguage(newLanguage);
    changeLanguage(newLanguage);
  };

  const isTelugu = language === "te";

  const services = [
    {
      icon: "🌱",
      en: "Paddy Planting",
      te: "వరి నాట్లు వేయడం",
      descriptionEn: "Planting young rice seedlings in the field.",
      descriptionTe: "పొలంలో వరి నారు నాటడం.",
    },
    {
      icon: "🌾",
      en: "Harvesting",
      te: "పంట కోత",
      descriptionEn: "Collecting mature crops from the field.",
      descriptionTe: "పంట చేతికి వచ్చినప్పుడు కోయడం.",
    },
    {
      icon: "🌿",
      en: "Weeding",
      te: "కలుపు తీయడం",
      descriptionEn: "Removing unwanted plants from crops.",
      descriptionTe: "పంటలోని కలుపు మొక్కలను తొలగించడం.",
    },
    {
      icon: "💧",
      en: "Irrigation",
      te: "నీటి పారుదల",
      descriptionEn: "Supplying water to agricultural fields.",
      descriptionTe: "పంట పొలాలకు నీటిని అందించడం.",
    },
    {
      icon: "🚜",
      en: "Land Preparation",
      te: "భూమి సిద్ధం చేయడం",
      descriptionEn: "Preparing soil before cultivation.",
      descriptionTe: "సాగుకు ముందు భూమిని సిద్ధం చేయడం.",
    },
    {
      icon: "🌻",
      en: "Fertilizer Application",
      te: "ఎరువులు వేయడం",
      descriptionEn: "Applying fertilizers to support crop growth.",
      descriptionTe: "పంట పెరుగుదలకు ఎరువులు వేయడం.",
    },
  ];

  return (
    <div className="app-container">
      {!started ? (
        <div className="language-card">
          <div className="app-logo">🌾</div>

          <h1>Harvest Hub</h1>

          <p className="tagline">
            Connecting Farmers and Workers
          </p>

          <h2>Choose Your Language</h2>
          <h3>మీ భాషను ఎంచుకోండి</h3>

          <div className="language-options">
            <button
              className={
                selectedLanguage === "en"
                  ? "language-btn selected"
                  : "language-btn"
              }
              onClick={() => setSelectedLanguage("en")}
            >
              🇬🇧 English
            </button>

            <button
              className={
                selectedLanguage === "te"
                  ? "language-btn selected"
                  : "language-btn"
              }
              onClick={() => setSelectedLanguage("te")}
            >
              🇮🇳 తెలుగు
            </button>
          </div>

          <button
            className="continue-btn"
            onClick={handleContinue}
          >
            Continue / కొనసాగించండి →
          </button>
        </div>
      ) : (
        <div
          style={{
            width: "100%",
            minHeight: "100vh",
            background: "#f0f7f1",
          }}
        >
          {/* Header */}
          <header
            style={{
              background: "#ffffff",
              padding: "15px 5%",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
              gap: "15px",
              boxShadow: "0 2px 10px rgba(0,0,0,0.06)",
            }}
          >
            <h2
              style={{
                color: "#167044",
                margin: 0,
                fontSize: "25px",
              }}
            >
              🌾 Harvest Hub
            </h2>

            {/* Right side buttons */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-end",
                flexWrap: "wrap",
                gap: "10px",
              }}
            >
              <select
                value={language}
                onChange={(e) =>
                  handleLanguageChange(e.target.value)
                }
                aria-label="Change language"
                style={{
                  padding: "10px",
                  borderRadius: "8px",
                  border: "1px solid #d1d5db",
                  background: "#ffffff",
                  cursor: "pointer",
                }}
              >
                <option value="en">English</option>
                <option value="te">తెలుగు</option>
              </select>

              <button
                onClick={() => navigate("/farmer-login")}
                style={{
                  padding: "10px 16px",
                  border: "1px solid #167044",
                  borderRadius: "8px",
                  background: "#167044",
                  color: "#ffffff",
                  fontWeight: "600",
                  cursor: "pointer",
                }}
              >
                👨‍🌾 {isTelugu ? "రైతు లాగిన్" : "Farmer Login"}
              </button>

              <button
                onClick={() => navigate("/worker-login")}
                style={{
                  padding: "10px 16px",
                  border: "1px solid #2563eb",
                  borderRadius: "8px",
                  background: "#2563eb",
                  color: "#ffffff",
                  fontWeight: "600",
                  cursor: "pointer",
                }}
              >
                👷 {isTelugu ? "కార్మికుల లాగిన్" : "Worker Login"}
              </button>
            </div>
          </header>

          {/* Hero Section */}
          <main
            style={{
              maxWidth: "1200px",
              margin: "0 auto",
              padding: "40px 20px",
            }}
          >
